function dancepad_chart(){var fallback=[15,21,12,12,15,9,22,17,25,28,42,45,51,38,42,69,69,79,77,78,70,94,91,99,99,85,95];function toNumber(value){var number=parseFloat(value);if(Number.isNaN(number)){return null}
if(number<0){return 0}
if(number>100){return 100}
return number}
function parseValues(rawValues){if(!rawValues){return[]}
return rawValues.split(",").map(function(value){return toNumber(value.trim())}).filter(function(value){return value!==null})}
function buildPaths(values){var vw=364;var vh=162;var pad=2;var n=values.length;if(n<2){return{line:"",area:""}}
var points=[];var step=(vw-2*pad)/(n-1);for(var i=0;i<n;i+=1){var x=Number((pad+i*step).toFixed(2));var y=Number((vh*(1-values[i]/100)).toFixed(2));points.push([x,y])}
var d="M"+points[0][0]+" "+points[0][1];for(var j=0;j<n-1;j+=1){var p0=j>0?points[j-1]:points[0];var p1=points[j];var p2=points[j+1];var p3=j+2<n?points[j+2]:points[n-1];var c1x=Number((p1[0]+(p2[0]-p0[0])/6).toFixed(2));var c1y=Number((p1[1]+(p2[1]-p0[1])/6).toFixed(2));var c2x=Number((p2[0]-(p3[0]-p1[0])/6).toFixed(2));var c2y=Number((p2[1]-(p3[1]-p1[1])/6).toFixed(2));d+="C"+c1x+" "+c1y+" "+c2x+" "+c2y+" "+p2[0]+" "+p2[1]}
return{line:d,area:d+"L"+points[n-1][0]+" "+vh+"L"+points[0][0]+" "+vh+"Z"}}
document.querySelectorAll(".dan-chart").forEach(function(element,index){var values=parseValues(element.getAttribute("data-values"));var paths=buildPaths(values.length>1?values:fallback);var linePath=element.querySelector(".dan-chart__line");var areaPath=element.querySelector(".dan-chart__area");var gradient=element.querySelector(".dan-chart__gradient");if(gradient&&areaPath){var gradientId="dan-chart-gradient-"+index;gradient.setAttribute("id",gradientId);areaPath.setAttribute("fill","url(#"+gradientId+")")}
if(linePath&&paths.line){linePath.setAttribute("d",paths.line)}
if(areaPath&&paths.area){areaPath.setAttribute("d",paths.area)}
if(element.getAttribute("data-loop")==="1"){element.classList.add("dan-chart--loop")}else{element.classList.remove("dan-chart--loop")}
element.removeAttribute("data-flickering");if(element._dancepadChartTrigger&&typeof element._dancepadChartTrigger.kill==="function"){element._dancepadChartTrigger.kill();element._dancepadChartTrigger=null}
if(typeof ScrollTrigger!=="undefined"){element.classList.remove("dan-chart--visible");element._dancepadChartTrigger=ScrollTrigger.create({trigger:element,start:"top bottom",end:"bottom top",toggleClass:"dan-chart--visible"})}else{element.classList.add("dan-chart--visible")}})}
document.addEventListener("DOMContentLoaded",function(){if(typeof bricksIsFrontend==="undefined"||bricksIsFrontend){dancepad_chart()}})